defmodule Alva.Codegen.DtoGenerator do
  @moduledoc """
  Generates TypeScript interfaces for Ash resources.
  """

  alias Alva.Codegen.TypeMapper

  def generate_types_ts(resources) do
    interfaces = 
      resources
      |> Enum.map(&generate_interface/1)
      |> Enum.join("\n\n")

    """
    // This file is auto-generated by Alva.
    // Do not edit manually.

    export type LiveResult<T> =
      | { ok: true; data: T; meta?: Record<string, any> }
      | { ok: false; error: any; meta?: Record<string, any> };

    export type FilterOps<V> = {
      eq?: V;
      not_eq?: V;
      in?: V[];
      is_nil?: boolean;
      less_than?: V;
      greater_than?: V;
      less_than_or_equal?: V;
      greater_than_or_equal?: V;
      lt?: V;
      gt?: V;
      lte?: V;
      gte?: V;
      contains?: string;
      ilike?: string;
      like?: string;
    };

    export type AshFilter<T> =
      | boolean
      | { and?: AshFilter<T>[] }
      | { or?: AshFilter<T>[] }
      | { not?: AshFilter<T> }
      | { [K in keyof T]?: T[K] | FilterOps<T[K]> | AshFilter<T[K]> };

    #{interfaces}
    """
  end

  def output_type(resource, event_def) do
    action = Ash.Resource.Info.action(resource, event_def.action)
    interface = interface_name(resource)
    
    if action.type == :read and is_nil(event_def.lookup) do
      "#{interface}[]"
    else
      interface
    end
  end

  def interface_name(resource) do
    resource |> Module.split() |> List.last()
  end

  defp generate_interface(resource) do
    name = interface_name(resource)
    
    # Optionality logic: if there are field policies, they might be redacted
    field_policies =
      if Code.ensure_loaded?(Ash.Policy.Info) and function_exported?(Ash.Policy.Info, :field_policies, 1) do
        apply(Ash.Policy.Info, :field_policies, [resource]) || []
      else
        []
      end

    policy_fields =
      field_policies
      |> Enum.flat_map(fn policy -> policy.fields end)
      |> Enum.uniq()

    attrs = Ash.Resource.Info.public_attributes(resource)
    calcs = Ash.Resource.Info.public_calculations(resource)
    aggs = Ash.Resource.Info.public_aggregates(resource)
    rels = Ash.Resource.Info.public_relationships(resource)

    fields_ts =
      (attrs ++ calcs ++ aggs)
      |> Enum.map(fn field ->
        optional? = is_optional?(field, policy_fields)
        ts_type = TypeMapper.map_type(field.type, Map.get(field, :constraints, []))
        format_field(field.name, ts_type, optional?)
      end)
      
    rels_ts = 
      rels
      |> Enum.map(fn rel ->
        optional? = true # Relationships might not always be loaded
        dest_name = interface_name(rel.destination)
        
        ts_type = 
          case rel.cardinality do
            :many -> "#{dest_name}[]"
            :one -> dest_name
          end
          
        format_field(rel.name, ts_type, optional?)
      end)

    all_fields = Enum.join(fields_ts ++ rels_ts, "\n")

    """
    export interface #{name} {
    #{all_fields}
    }
    """
  end

  defp is_optional?(field, policy_fields) do
    field.name in policy_fields or Map.get(field, :allow_nil?, true)
  end

  defp format_field(name, type, true = _optional?), do: "  #{name}?: #{type};"
  defp format_field(name, type, false = _optional?), do: "  #{name}: #{type};"
end
